// ==UserScript==
// @name         AniWaves Popup + Overlay Blocker
// @namespace    NotMeValo
// @version      2.0.0-userscript
// @description  Blocks popup redirects, invisible click shields, ad overlays and page-locking behavior on AniWaves.
// @author       NotMeValo
// @match        https://aniwaves.ru/*
// @match        https://*.aniwaves.ru/*
// @match        http://aniwaves.ru/*
// @match        http://*.aniwaves.ru/*
// @run-at       document-start
// @grant        none
// ==/UserScript==

(function () {
    'use strict';

    const DEBUG = false;

    const log = (...args) => {
        if (DEBUG) {
            console.log('[AniWaves Guard]', ...args);
        }
    };

    /******************************************************************
     * PAGE CONTEXT GUARD
     *
     * Inject directly into page context so the site's own JavaScript
     * sees the modified window.open / popup behavior.
     ******************************************************************/

    function installPageGuard() {
        const script = document.createElement('script');

        script.textContent = `
        (() => {
            'use strict';

            const blockedDomains = [
                'doubleclick.net',
                'googlesyndication.com',
                'googleadservices.com',
                'adsterra',
                'popads',
                'popcash',
                'propellerads',
                'onclick',
                'trafficjunky',
                'exoclick',
                'adnxs',
                'criteo',
                'taboola',
                'outbrain'
            ];

            const isAniWaves = host =>
                host === 'aniwaves.ru' ||
                host.endsWith('.aniwaves.ru');

            function isSuspiciousURL(value) {
                if (!value) return false;

                try {
                    const url = new URL(value, location.href);

                    if (url.protocol !== 'http:' &&
                        url.protocol !== 'https:') {
                        return false;
                    }

                    if (isAniWaves(url.hostname))
                        return false;

                    return blockedDomains.some(domain =>
                        url.hostname.includes(domain)
                    );

                } catch {
                    return false;
                }
            }

            /**********************************************************
             * BLOCK window.open POPUPS
             **********************************************************/

            const nativeOpen = window.open;

            Object.defineProperty(window, 'open', {
                configurable: true,
                writable: true,
                value: function(url, target, features) {

                    if (!url) {
                        console.debug('[AniWaves Guard] blocked empty popup');
                        return null;
                    }

                    try {
                        const parsed = new URL(url, location.href);

                        /*
                         * Allow same-site links.
                         */
                        if (isAniWaves(parsed.hostname)) {
                            return nativeOpen.call(
                                window,
                                url,
                                target,
                                features
                            );
                        }

                        /*
                         * Block known advertising domains.
                         */
                        if (isSuspiciousURL(url)) {
                            console.debug(
                                '[AniWaves Guard] popup blocked:',
                                url
                            );

                            return null;
                        }

                    } catch {}

                    /*
                     * Most popup advertising on streaming sites happens
                     * without a normal user gesture.
                     */
                    if (!navigator.userActivation?.isActive) {
                        console.debug(
                            '[AniWaves Guard] non-user popup blocked:',
                            url
                        );

                        return null;
                    }

                    /*
                     * User-clicked legitimate links are still allowed.
                     */
                    return nativeOpen.call(
                        window,
                        url,
                        target,
                        features
                    );
                }
            });


            /**********************************************************
             * BLOCK javascript: POPUP LINKS
             **********************************************************/

            document.addEventListener(
                'click',
                event => {

                    const element =
                        event.target.closest?.(
                            'a[href], area[href]'
                        );

                    if (!element)
                        return;

                    const href =
                        element.getAttribute('href');

                    if (!href)
                        return;

                    if (
                        href.trim()
                            .toLowerCase()
                            .startsWith('javascript:')
                    ) {

                        const code =
                            href.toLowerCase();

                        if (
                            code.includes('window.open') ||
                            code.includes('popup')
                        ) {

                            event.preventDefault();
                            event.stopImmediatePropagation();

                            console.debug(
                                '[AniWaves Guard] javascript popup blocked'
                            );
                        }
                    }

                },
                true
            );


            /**********************************************************
             * PROTECT location.assign / replace
             **********************************************************/

            try {

                const nativeAssign =
                    Location.prototype.assign;

                const nativeReplace =
                    Location.prototype.replace;

                Location.prototype.assign =
                    function(url) {

                        if (isSuspiciousURL(url)) {
                            console.debug(
                                '[AniWaves Guard] redirect blocked:',
                                url
                            );

                            return;
                        }

                        return nativeAssign.call(
                            this,
                            url
                        );
                    };

                Location.prototype.replace =
                    function(url) {

                        if (isSuspiciousURL(url)) {

                            console.debug(
                                '[AniWaves Guard] redirect blocked:',
                                url
                            );

                            return;
                        }

                        return nativeReplace.call(
                            this,
                            url
                        );
                    };

            } catch {}


            /**********************************************************
             * BLOCK FAKE CLICK REDIRECTS
             **********************************************************/

            let lastTrustedClick = 0;

            document.addEventListener(
                'pointerdown',
                event => {

                    if (event.isTrusted)
                        lastTrustedClick =
                            Date.now();

                },
                true
            );

            document.addEventListener(
                'click',
                event => {

                    if (!event.isTrusted)
                        return;

                    lastTrustedClick =
                        Date.now();

                },
                true
            );


            /**********************************************************
             * prevent fake popup mouse events
             **********************************************************/

            const popupEvents = [
                'mouseup',
                'mousedown',
                'pointerup',
                'touchend'
            ];

            popupEvents.forEach(type => {

                document.addEventListener(
                    type,
                    event => {

                        const target =
                            event.target;

                        if (
                            target === document.body ||
                            target === document.documentElement
                        ) {

                            return;
                        }

                    },
                    true
                );

            });

        })();
        `;

        (document.documentElement ||
         document.head ||
         document).appendChild(script);

        script.remove();
    }


    installPageGuard();


    /******************************************************************
     * ELEMENT CLASSIFICATION
     ******************************************************************/

    const suspiciousWords = [
        'popup',
        'popunder',
        'pop-under',
        'advert',
        'advertisement',
        'ad-overlay',
        'ad_overlay',
        'admodal',
        'ad-modal',
        'clickunder',
        'click-under',
        'redirect-overlay',
        'interstitial',
        'sponsor-overlay'
    ];


    function textContainsSuspiciousWord(value) {

        if (!value)
            return false;

        const text =
            String(value)
                .toLowerCase();

        return suspiciousWords.some(
            word => text.includes(word)
        );
    }


    function elementLooksSuspicious(el) {

        if (!(el instanceof HTMLElement))
            return false;

        /*
         * Never touch actual media elements.
         */
        if (
            el.matches(
                'video, audio, source, track, iframe'
            )
        ) {
            return false;
        }

        const id =
            el.id || '';

        const className =
            typeof el.className === 'string'
                ? el.className
                : '';

        if (
            textContainsSuspiciousWord(id) ||
            textContainsSuspiciousWord(className)
        ) {
            return true;
        }

        return false;
    }


    /******************************************************************
     * INVISIBLE CLICK SHIELD DETECTION
     ******************************************************************/

    function isClickShield(el) {

        if (!(el instanceof HTMLElement))
            return false;

        /*
         * Avoid touching player controls.
         */
        if (
            el.closest(
                'video, .plyr, .jwplayer, .video-js'
            )
        ) {
            return false;
        }

        const style =
            getComputedStyle(el);

        const position =
            style.position;

        if (
            position !== 'fixed' &&
            position !== 'absolute'
        ) {
            return false;
        }

        const rect =
            el.getBoundingClientRect();

        if (
            rect.width <
            window.innerWidth * 0.75
        ) {
            return false;
        }

        if (
            rect.height <
            window.innerHeight * 0.75
        ) {
            return false;
        }

        /*
         * High z-index full-page layers are common
         * popup redirect shields.
         */
        const zIndex =
            Number.parseInt(
                style.zIndex,
                10
            );

        if (
            Number.isFinite(zIndex) &&
            zIndex >= 999
        ) {

            /*
             * Don't remove visible legitimate dialogs.
             */
            const opacity =
                Number.parseFloat(
                    style.opacity || '1'
                );

            const bg =
                style.backgroundColor;

            const hasVeryLittleContent =
                (el.innerText || '')
                    .trim()
                    .length < 30;

            if (
                opacity <= 0.15 ||
                bg === 'rgba(0, 0, 0, 0)' ||
                bg === 'transparent' ||
                hasVeryLittleContent
            ) {

                return true;
            }
        }

        return false;
    }


    /******************************************************************
     * PAGE UNLOCK
     ******************************************************************/

    function unlockPage() {

        const html =
            document.documentElement;

        const body =
            document.body;

        if (html) {

            if (
                html.style.overflow === 'hidden'
            ) {
                html.style.overflow = '';
            }

            if (
                html.style.pointerEvents === 'none'
            ) {
                html.style.pointerEvents = '';
            }
        }

        if (body) {

            if (
                body.style.overflow === 'hidden'
            ) {
                body.style.overflow = '';
            }

            if (
                body.style.pointerEvents === 'none'
            ) {
                body.style.pointerEvents = '';
            }
        }
    }


    /******************************************************************
     * REMOVE BAD NODE
     ******************************************************************/

    function removeSafely(el) {

        try {

            if (
                !el ||
                !el.isConnected
            ) {
                return;
            }

            log(
                'Removing:',
                el
            );

            el.remove();

        } catch {
            /*
             * Ignore mutation race conditions.
             */
        }
    }


    /******************************************************************
     * CLEAN PAGE
     ******************************************************************/

    function cleanPage(root = document) {

        if (!root)
            return;

        let elements;

        try {

            elements =
                root.querySelectorAll?.(
                    'div, section, aside, dialog'
                );

        } catch {
            return;
        }

        if (!elements)
            return;

        for (
            const el of elements
        ) {

            if (
                elementLooksSuspicious(el) ||
                isClickShield(el)
            ) {

                removeSafely(el);
            }
        }

        unlockPage();
    }


    /******************************************************************
     * MUTATION OBSERVER
     ******************************************************************/

    const observer =
        new MutationObserver(
            mutations => {

                for (
                    const mutation
                    of mutations
                ) {

                    for (
                        const node
                        of mutation.addedNodes
                    ) {

                        if (
                            !(node instanceof HTMLElement)
                        ) {
                            continue;
                        }

                        if (
                            elementLooksSuspicious(node) ||
                            isClickShield(node)
                        ) {

                            removeSafely(node);

                            continue;
                        }

                        cleanPage(node);
                    }
                }

                unlockPage();
            }
        );


    function startObserver() {

        if (
            !document.documentElement
        ) {

            requestAnimationFrame(
                startObserver
            );

            return;
        }

        observer.observe(
            document.documentElement,
            {
                childList: true,
                subtree: true
            }
        );

        cleanPage();
    }


    startObserver();


    /******************************************************************
     * PERIODIC CLEANUP
     *
     * Some ad scripts regenerate overlays several seconds later.
     ******************************************************************/

    setInterval(
        () => {

            cleanPage();
            unlockPage();

        },
        1500
    );


    /******************************************************************
     * REMOVE common inline popup handlers
     ******************************************************************/

    document.addEventListener(
        'DOMContentLoaded',
        () => {

            const attrs = [
                'onclick',
                'onmousedown',
                'onmouseup',
                'onpointerdown',
                'onpointerup'
            ];

            const elements =
                document.querySelectorAll(
                    '[onclick], [onmousedown], [onmouseup], [onpointerdown], [onpointerup]'
                );

            for (
                const el of elements
            ) {

                /*
                 * Avoid breaking player controls.
                 */
                if (
                    el.closest(
                        '.plyr, .jwplayer, .video-js'
                    )
                ) {
                    continue;
                }

                for (
                    const attr of attrs
                ) {

                    const value =
                        el.getAttribute(attr);

                    if (!value)
                        continue;

                    const lower =
                        value.toLowerCase();

                    if (
                        lower.includes(
                            'window.open'
                        ) ||
                        lower.includes(
                            'popunder'
                        ) ||
                        lower.includes(
                            'popup'
                        )
                    ) {

                        el.removeAttribute(
                            attr
                        );

                        log(
                            'Removed popup handler',
                            el
                        );
                    }
                }
            }

            cleanPage();
        }
    );


    log(
        'AniWaves userscript guard active'
    );

})();
